import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";

const Home = () => {
  const [showFooter, setShowFooter] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      const targetElement = document.getElementById("sanskriti");
      if (targetElement) {
        const rect = targetElement.getBoundingClientRect();
        setShowFooter(rect.top <= window.innerHeight / 2.5); // Adjust trigger point
      }
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <>
      <div className="relative bg-red-600 text-white min-h-screen">
        <div className="flex flex-row mx-auto w-fit">
          <div className="flex flex-col justify-center items-center text-center p-4">
            {/* Graphic and Communication Designer in a different format */}
            <span className="text-3xl italic mt-60 text-center">
              GRAPHIC AND COMMUNICATION DESIGNER
            </span>
            <span className="font-extrabold text-8xl mt-10 text-center">
              Hi there!
            </span>
            <span id="sanskriti" className="font-extrabold text-8xl text-center">
              I'm Sanskriti.
            </span>
            <span className="font-extrabold text-4xl mt-10 text-center">
              PORTFOLIO 2024
            </span>
          </div>
        </div>
      </div>

      <div
        className={`fixed bottom-0 left-0 w-full h-[40vh] bg-black transition-opacity duration-500 ${
          showFooter ? "opacity-100" : "opacity-0 pointer-events-none"
        }`}
      ></div>
    </>
  );
};

export default Home;
